  function territoryStaysConnected(schoolId,removedIndex){const cells=state.map.filter(c=>c.school===schoolId&&c.index!==removedIndex).map(c=>c.index);if(cells.length<2)return cells.length===1;const seen=new Set([cells[0]]),queue=[cells[0]];while(queue.length){mapNeighbors(queue.shift()).forEach(n=>{if(!seen.has(n)&&state.map[n].school===schoolId&&n!==removedIndex){seen.add(n);queue.push(n)}})}return seen.size===cells.length}
