  function openJointExamPlanner(targetId){if(state.money<35000)return toast('预约联考至少需要 ¥35,000。');if(state.actionPoints<1)return toast('本周行动点不足。');examTargetId=targetId;const target=school(targetId),min=new Date(getDate());min.setDate(min.getDate()+3);const max=new Date(getDate());max.setDate(max.getDate()+60);$('#exam-modal-title').textContent=`与${target.name}制定联考方案`;$('#exam-target-note').textContent='联考是校际学业比较，不会立即改变地块归属；成绩只会推进影响力渗透。';const date=$('#joint-exam-date');date.min=isoDay(min);date.max=isoDay(max);date.value=isoDay(min);const teachers=state.staffIds.map(staffById).filter(Boolean).sort((a,b)=>(b.stats[0]+b.stats[2]+b.stats[3])-(a.stats[0]+a.stats[2]+a.stats[3]));$('#joint-exam-teacher').innerHTML=teachers.map(t=>`<option value="${t.id}">${t.name} · ${t.subject} · 带队 ${teacherCommand(t).toFixed(1)}</option>`).join('');$$('[data-exam-grade]').forEach((b,i)=>b.checked=i===0);renderExamClassPickers();$('#exam-modal').hidden=false;date.onchange=renderExamPlanSummary;$('#joint-exam-teacher').onchange=renderExamPlanSummary;$$('[data-exam-grade]').forEach(b=>b.onchange=renderExamClassPickers)}
  function renderExamClassPickers(){const grades=$$('[data-exam-grade]:checked').map(x=>Number(x.dataset.examGrade));$('#exam-class-pickers').innerHTML=grades.flatMap(g=>[1,2,3,4,5,6].map(c=>`<label><input type="checkbox" data-exam-class="${classKey(g,c)}" checked><span>${classLabel(classKey(g,c))}</span><small>${c>=5?'精英班':c===4?'文科班':'理科班'} · ${c>=5?20:30} 人</small></label>`)).join('');$$('[data-exam-class]').forEach(b=>b.addEventListener('change',renderExamPlanSummary));renderExamPlanSummary()}
