    const general=teacherCommand(teacher),oppGeneral=D.clamp(35+target.power*.55+(rng()-.5)*10,38,94),schoolState=state.teacherSatisfaction*.22+state.studentSatisfaction*.18+state.safety*.18+state.adminEfficiency*.17+state.stability*.25,oppSchoolState=D.clamp(43+target.power*.42+(rng()-.5)*7,38,92),schoolLevel=state.academics*.55+state.teaching*.25+state.power*.2,oppSchoolLevel=D.clamp((target.exam-400)/3*.62+target.power*.38,35,96),qtyHome=D.clamp(50+(effectiveQty-oppQty)/Math.max(effectiveQty,oppQty)*50,20,80),qtyAway=100-qtyHome;
