  function filterPeople(){const filters=$('#people-filters');if(!filters)return;filters.hidden=false;const q=$('#people-search').value.trim().toLowerCase(),subject=$('#people-subject').value,min=Number($('#people-min').value),rows=$$(peopleTab==='management'?'#people-content .role-card':'#people-content .person-row');let count=0;rows.forEach(row=>{const id=row.dataset.person||row.querySelector('[data-person]')?.dataset.person,t=staffById(id),isPrincipal=!!row.querySelector('[data-principal]'),score=t?.overall??(isPrincipal?principal().stats.reduce((a,b)=>a+b,0)/6:0),matches=(!q||row.textContent.toLowerCase().includes(q))&&(!subject||t?.subject===subject)&&score>=min;row.hidden=!matches;if(matches)count++});$('#people-filter-count').textContent=count?`显示 ${count} / ${rows.length} 项`:'没有匹配人员，请调整搜索或筛选条件。'}
  function roleEffectTags(def,fit=100){const names={adminEfficiency:'行政',staffSatisfaction:'职工',teacherSatisfaction:'教师',studentSatisfaction:'学生',safety:'安全',authority:'权威',teaching:'教学',academics:'学业',prestige:'声望',teacherGrowth:'师资成长',studentAcademic:'学业成长',studentDiscipline:'学生自律',studentMindset:'学生心态',expenseReduction:'运营节支'};return Object.entries(def.effects).slice(0,4).map(([key,value])=>`<span>${names[key]||key} +${(value*fit/100).toFixed(2)}</span>`).join('')}
  function roleCard(role){const def=roleDef(role),id=state.roles[role];if(!id)return`<article class="role-card empty rank-${def.rank}"><span class="role">${def.tier} · ${role}</span><h3>职位空缺</h3><small>${def.focus}</small><div class="role-effects muted">${roleEffectTags(def)}</div><button class="btn btn-secondary" data-role-choose="${role}">选择教师或待任人才</button></article>`;const t=staffById(id),fit=roleFit(role,t);return`<article class="role-card rank-${def.rank}"><span class="role">${def.tier} · ${role}</span><h3>${t.name}</h3><div class="role-fit has-tooltip" tabindex="0" data-tooltip="由此岗位的六维权重与任职者能力共同计算；适配越高，每周治理增益越强。"><span>岗位适配</span><b>${fit}</b><i><em style="width:${fit}%"></em></i></div><div class="role-effects">${roleEffectTags(def,fit)}</div><button class="btn btn-secondary" data-person="${t.id}">查看职责与任职档案</button></article>`}
  function personRow(t,note=''){return`<article class="person-row" tabindex="0" data-person="${t.id}"><span class="person-avatar">${t.name[0]}</span><div><strong>${t.name}</strong><p>${t.subject} · ${t.trait}${note?`<br>${note}`:''}</p></div><span class="stars">${'★'.repeat(t.stars)}</span></article>`}
