    $('#facility-detail').innerHTML=`<div class="facility-detail-head"><div><p class="kicker">${selected.area} · 资产管理</p><h3>${selected.name}</h3></div><b>Lv.${selected.level}/10</b></div><p>${selected.desc}</p><div class="facility-tier"><span>当前档次</span><strong>${facilityTierName(selected.level)}</strong><i><em style="width:${selected.level*10}%"></em></i></div><dl><div><dt>当前持续效果</dt><dd>${selected.level?facilityEffectText(selected,selected.level):'无；停用区域会拖累校园评价'}</dd></div><div><dt>升级后新增</dt><dd>${selected.level<selected.max?`${facilityEffectText(selected)} · 费用 ${fmtMoney(cost)}`:'已达到最高档次'}</dd></div></dl><div class="facility-actions"><button class="btn btn-primary" data-facility-action="upgrade" ${selected.level>=selected.max||state.money<cost?'disabled':''}>升级到 Lv.${Math.min(10,selected.level+1)}</button><button class="btn btn-secondary" data-facility-action="downgrade" ${selected.level<=0?'disabled':''}>降低标准 · 回收 ${fmtMoney(downRefund)}</button><button class="btn btn-danger" data-facility-action="sell" ${selected.level<=0?'disabled':''}>变卖停用 · 收益 ${fmtMoney(sale)}</button></div><p class="facility-warning">降标会损失对应持续效果并降低满意度；变卖还会降低声望、安全与校长权威。</p>`;
