  function applySchoolPolicy(policyId,optionId){const def=D.schoolPolicyDefinitions.find(x=>x.id===policyId),next=def?.options.find(x=>x.id===optionId),current=def?.options.find(x=>x.id===state.schoolPolicies[policyId]);if(!def||!next||next===current)return;if(state.actionPoints<1)return toast('修改学校政策需要 1 点行动力。');if(!confirm(`确定将“${def.name}”调整为“${next.name}”吗？\n政策将从今天起影响学生愤怒、日常成长与学校稳定度。`))return;state.actionPoints--;const angerShock=((next.effects.studentAnger||0)-(current?.effects.studentAnger||0))*8;state.students.forEach(s=>s.anger=D.clamp(s.anger+angerShock,0,100));state.studentSatisfaction+=(next.effects.studentSatisfaction||0)-(current?.effects.studentSatisfaction||0);state.authority+=((next.effects.authority||0)-(current?.effects.authority||0))*.35;state.schoolPolicies[policyId]=optionId;state.policyChanges.unshift({date:isoDay(getDate()),policyId,optionId});state.policyChanges=state.policyChanges.slice(0,30);state.stability=stabilitySnapshot().value;addCalendarEvent('action',`颁布：${def.name}·${next.name}`);addNews(`学校颁布“${def.name}—${next.name}”，学生与教职工开始适应新制度。`);clampStats();save();renderAll();showView('policies');toast('政策已经颁布，效果从今日起生效。')}
  function effectChips(e){const names={teaching:'教学',power:'实力',academics:'学业',morale:'学生满意',staffSatisfaction:'职工满意',teacherSatisfaction:'教师满意',authority:'权威',prestige:'声望',safety:'安全',teacherGrowth:'教师成长',recruit:'人才库',sponsor:'社会资金',austerity:'全员奖金下调'};return Object.entries(e).filter(([k,v])=>v&&typeof v!=='object').slice(0,4).map(([k,v])=>`<span>${names[k]||k}${typeof v==='number'?` ${v>0?'+':''}${v}`:''}</span>`).join('')}
  function renderActions(){if(!state)return;$('#ap-label').textContent=`${state.actionPoints} / ${state.maxActionPoints}`;const next=state.scheduledEvents.filter(e=>e.status==='scheduled').sort((a,b)=>a.date.localeCompare(b.date))[0],reformBonus=(principal().stats[4]-50)*.2;$('#action-command').innerHTML=`<div><p class="kicker">当前校务周期</p><h3>${fmtDate(state.date)} · ${schoolSeason(getDate())}</h3><span>下周一恢复至 ${state.maxActionPoints} 点行动力 · 改革能力使正向效果 ${signed(reformBonus,1)}%</span></div><div><small>最近预约</small><strong>${next?`${fmtDate(`${next.date}T12:00:00`)} 与${school(next.targetId).short}联考`:'暂无已预约联考'}</strong></div><button class="btn btn-secondary" data-plan-exam>前往版图预约联考</button>`;$('[data-plan-exam]').addEventListener('click',()=>showView('map'));const exclusive=principal().bonus.inspire?`<article class="action-card principal-action compact-action"><i class="action-mark">鼓</i><p class="kicker">侯鸿杰专属 · 考前</p><h3>鼓舞人心</h3><p>消耗校长权威，使下一场月考、联考或高考模拟中全体学生成绩提高 10%。只触发一次，不可叠加。</p><div class="effect-chips"><span>下一场成绩 +10%</span><span>${state.principalSkills.examBoost?'效果已待命':'尚未启用'}</span></div><div class="action-cost"><span>5 校长权威</span><span>不消耗行动点</span></div><button class="btn btn-primary btn-block" data-principal-action="encourage" ${state.authority<5||state.principalSkills.examBoost?'disabled':''}>${state.principalSkills.examBoost?'等待下一场考试':'执行鼓舞'}</button></article><article class="action-card principal-action compact-action"><i class="action-mark">振</i><p class="kicker">侯鸿杰专属 · 日常</p><h3>振奋人心</h3><p>面向全校发表动员讲话，立即使每名学生的愤怒值降低 5 点。</p><div class="effect-chips"><span>全校愤怒 −5</span><span>稳定度间接受益</span></div><div class="action-cost"><span>10 校长权威</span><span>不消耗行动点</span></div><button class="btn btn-primary btn-block" data-principal-action="rally" ${state.authority<10?'disabled':''}>执行振奋</button></article>`:'';const groups=[['教学与成绩',['teach','materials']],['学生与校园',['visit','club','care','safety']],['人才与资源',['recruit','sponsor','public']],['财政管理',['austerity']]];$('#action-grid').innerHTML=(exclusive?'<h3 class="action-group-title">校长专属</h3>'+exclusive:'')+groups.map(([name,ids])=>`<h3 class="action-group-title">${name}</h3>`+ids.map(id=>D.actions.find(a=>a.id===id)).filter(Boolean).map(a=>`<article class="action-card compact-action"><h3>${a.title}</h3><p>${a.desc}</p><div class="effect-chips">${effectChips(a.effects)}</div><div class="action-cost"><span>${fmtMoney(a.money)}</span><span>${a.ap} 行动点</span></div><button class="btn btn-primary btn-block" data-action="${a.id}" ${state.money<a.money||state.actionPoints<a.ap?'disabled':''}>执行行动</button></article>`).join('')).join('');$$('[data-action]').forEach(b=>b.addEventListener('click',()=>doAction(b.dataset.action)));$$('[data-principal-action]').forEach(b=>b.addEventListener('click',()=>runPrincipalAction(b.dataset.principalAction)))}
  function runPrincipalAction(id){if(!principal().bonus.inspire)return;if(id==='encourage'){if(state.authority<5||state.principalSkills.examBoost)return toast('权威不足或鼓舞效果已经待命。');state.authority-=5;state.principalSkills.examBoost=true;addNews('侯鸿杰完成考前动员：下一场考试全体学生成绩提高 10%。');addCalendarEvent('action','鼓舞人心')}if(id==='rally'){if(state.authority<10)return toast('校长权威不足。');state.authority-=10;state.students.forEach(s=>s.anger=D.clamp(s.anger-5,0,100));state.studentSatisfaction+=.5;addNews('侯鸿杰发表全校讲话，所有学生愤怒值降低 5 点。');addCalendarEvent('action','振奋人心')}state.stability=stabilitySnapshot().value;clampStats();save();renderAll();toast(id==='encourage'?'鼓舞效果已待命，将由下一场考试消耗。':'振奋人心已执行，全校愤怒值下降。')}
  function doAction(id){
    const a=D.actions.find(x=>x.id===id);if(state.money<a.money||state.actionPoints<a.ap)return;
    state.money-=a.money;state.actionPoints-=a.ap;ledger(a.title,-a.money);addCalendarEvent('action',a.title);
    if(a.policy){const effects={...a.policy};delete effects.days;state.activePolicies.push({id:`${a.id}-${state.day}`,name:a.title,remaining:a.policy.days,effects})}
    const e=a.effects,scale=1+(principal().stats[4]-50)*.002,v=k=>typeof e[k]==='number'&&e[k]>0?e[k]*scale:e[k];if(e.teaching){state.teaching+=v('teaching');state.teacherSatisfaction+=v('teaching')*.35}if(e.power)state.power+=v('power');if(e.academics)state.academics+=v('academics');if(e.morale)state.studentSatisfaction+=v('morale');if(e.staffSatisfaction)state.staffSatisfaction+=v('staffSatisfaction');if(e.teacherSatisfaction)state.teacherSatisfaction+=v('teacherSatisfaction');if(e.authority)state.authority+=v('authority');if(e.prestige)state.prestige+=v('prestige');if(e.safety)state.safety+=v('safety');
    if(e.teacherGrowth)state.staffIds.slice(0,10).forEach(id=>staffById(id).stats[4]=D.clamp(staffById(id).stats[4]+v('teacherGrowth'),0,100));if(e.recruit){state.recruitSeed=(state.recruitSeed+36)%(allStaff.length-40);peopleTab='market'}
    if(e.austerity){state.salaryPolicy=round2(Math.max(.75,state.salaryPolicy-.1));addNews(`全校奖金标准下调至 ${Math.round(state.salaryPolicy*100)}%，教职工队伍出现强烈不满。`)}
    if(e.sponsor){const amount=Math.round(40000+principal().stats[2]*900+state.prestige*500+Math.random()*60000);state.money+=amount;state.authority+=1;ledger('校友企业专项资助',amount);addNews(`校友企业承诺提供 ${fmtMoney(amount)} 专项资助。`)}else addNews(`学校完成“${a.title}”。`);
    clampStats();save();renderAll();toast(`“${a.title}”已执行。${e.recruit?'人才市场已刷新。':''}`)
  }

  function dailyStudentUpdate(){
    const g=governanceSnapshot(),p=policyTotals(),sp=schoolPolicyTotals(),facilities=facilityTotals(),examSoon=state.scheduledEvents.some(e=>{const diff=new Date(`${e.date}T12:00:00`)-getDate();return e.status==='scheduled'&&diff>=0&&diff<=7*86400000}),admin=(state.adminEfficiency-50)*.00016;
    const classEfficiency={};Object.keys(state.classTeachers).forEach(key=>{const c=Number(key.split('-')[1]),subjects=curriculumSubjects(c);classEfficiency[key]=subjects.reduce((sum,subject)=>sum+subjectEfficiency(key,subject),0)/subjects.length});let mindsetTotal=0;
    state.students.forEach(s=>{
      const gradeEffects={studentAcademic:0,studentDiscipline:0,studentMindset:0};g.entries.forEach(entry=>{const def=roleDef(entry.role);if(def.grade===s.grade)Object.keys(gradeEffects).forEach(k=>gradeEffects[k]+=(def.effects[k]||0)*entry.fit)});
      const assignment=state.classTeachers[classKey(s.grade,s.classNo)],missingSubjects=curriculumSubjects(s.classNo).filter(subject=>!assignment?.subjects?.[subject]||!state.staffIds.includes(assignment.subjects[subject])).length,missingHomeroom=!assignment?.homeroomId||!state.staffIds.includes(assignment.homeroomId),vacancyPenalty=missingSubjects*.018+(missingHomeroom?.008:0),potentialGap=s.stats[4]-s.stats[0];
      const academic=potentialGap*.00038+(state.teaching-50)*.00032+(state.teacherSatisfaction-50)*.00012+(principal().stats[1]-50)*.00008+g.totals.studentAcademic*.00045+gradeEffects.studentAcademic*.0008+(p.studentAcademic||0)+(sp.studentAcademic||0)+(facilities.studentAcademic||0)-vacancyPenalty-s.anger*.000035+((classEfficiency[classKey(s.grade,s.classNo)]??50)-60)*.0005+(Math.random()-.5)*.008;
      const disciplineTarget=D.clamp(48+state.adminEfficiency*.22+state.teacherSatisfaction*.12+g.totals.studentDiscipline*.12+gradeEffects.studentDiscipline*.16,30,92),discipline=(disciplineTarget-s.stats[1])*.0018+(p.studentDiscipline||0)+(sp.studentDiscipline||0)+(Math.random()-.5)*.01;
      const mindsetTarget=D.clamp(18+state.studentSatisfaction*.42+state.safety*.2+state.teacherSatisfaction*.12+gradeEffects.studentMindset*.12-(examSoon?4:0)-missingSubjects*1.5-s.anger*.08,22,94),mindset=(mindsetTarget-s.stats[2])*.0035+(p.studentMindset||0)+(sp.studentMindset||0)-vacancyPenalty*.25+(Math.random()-.5)*.014;
      const angerTarget=D.clamp(50-state.studentSatisfaction*.28-state.safety*.08+(examSoon?5:0)+missingSubjects*2+(missingHomeroom?2:0)+(s.trait==='情绪敏感'?7:0),4,88),anger=(angerTarget-s.anger)*.012+(sp.studentAnger||0)*.18-(p.studentMindset||0)*.45+(Math.random()-.5)*.018;
      s.stats[0]=D.clamp(s.stats[0]+academic,0,100);s.stats[1]=D.clamp(s.stats[1]+discipline+admin,0,100);s.stats[2]=D.clamp(s.stats[2]+mindset,0,100);s.stats[3]=D.clamp(s.stats[3]+(p.studentSocial||0),0,100);s.anger=D.clamp(s.anger+anger,0,100);s.dailyChange={academic:round2(academic),discipline:round2(discipline+admin),mindset:round2(mindset),anger:round2(anger)};s.composite=round2(s.stats[0]*.42+s.stats[1]*.14+s.stats[2]*.14+s.stats[3]*.1+s.stats[4]*.12+s.stats[5]*.08);s.tier=D.tierOf(s.composite);mindsetTotal+=s.stats[2]
    });
    const vacancies=vacancyReport();state.studentSatisfaction+=(mindsetTotal/state.students.length-state.studentSatisfaction)*.0015+(sp.studentSatisfaction||0)*.01-Math.min(.08,vacancies.total*.002);state.teacherSatisfaction+=(p.teacherSatisfaction||0)+(sp.teacherSatisfaction||0)*.015-Math.min(.04,vacancies.total*.001);state.activePolicies.forEach(x=>x.remaining--);state.activePolicies=state.activePolicies.filter(x=>x.remaining>0);state.stability=stabilitySnapshot().value
  }
  function applyFacilityWeekly(){const f=facilityTotals();state.teaching+=f.teaching*.08;state.academics+=f.academics*.08;state.studentSatisfaction+=f.studentSatisfaction*.045;state.safety+=f.safety*.06;state.adminEfficiency+=f.adminEfficiency*.05;state.staffSatisfaction+=f.staffSatisfaction*.04;state.prestige+=f.prestige*.03}
