  function applyWeeklyGovernance(){const before={power:state.power,teaching:state.teaching,academics:state.academics,staffSatisfaction:state.staffSatisfaction,teacherSatisfaction:state.teacherSatisfaction,studentSatisfaction:state.studentSatisfaction,safety:state.safety,authority:state.authority,adminEfficiency:state.adminEfficiency,stability:state.stability},g=governanceSnapshot(),t=g.totals;state.adminEfficiency=D.clamp(g.derivedAdmin+state.adminModifier,0,100);state.teaching+=t.teaching*.0016;state.academics+=t.academics*.0013;const staffTarget=D.clamp(48+t.staffSatisfaction*.22+state.adminEfficiency*.12,30,92),teacherTarget=D.clamp(52+t.teacherSatisfaction*.28+state.teaching*.15,30,92),studentTarget=D.clamp(48+t.studentSatisfaction*.2+state.safety*.08,30,92),safetyTarget=D.clamp(55+t.safety*.22,35,96);state.staffSatisfaction+=(staffTarget-state.staffSatisfaction)*.045;state.teacherSatisfaction+=(teacherTarget-state.teacherSatisfaction)*.045;state.studentSatisfaction+=(studentTarget-state.studentSatisfaction)*.04;state.safety+=(safetyTarget-state.safety)*.035;state.authority+=t.authority*.0006+(state.adminEfficiency>=65?.18:-.04);state.prestige+=t.prestige*.001;state.stability=stabilitySnapshot().value;state.power+=(state.adminEfficiency+state.teaching+state.safety+state.stability-220)*.0008;state.lastWeeklyDelta={};Object.keys(before).forEach(k=>state.lastWeeklyDelta[k]=round2(state[k]-before[k]));clampStats()}
