  function showEventFeedback(){const f=state.eventFeedback;if(!f)return;$('#event-tag').textContent='批示反馈';$('#event-title').textContent=f.title;$('#event-date').textContent=fmtDate(state.date);$('#event-icon').textContent='回';$('#event-text').textContent=f.story;$('.event-prompt').textContent='实际变化';$('#event-choices').replaceChildren();const details=document.createElement('p');details.textContent=f.changes;$('#event-choices').append(details);if(f.followup){const note=document.createElement('p');note.textContent='待跟进：相关事项已记入后续清单，最早一周后进入简报。';$('#event-choices').append(note)}const button=document.createElement('button');button.className='btn btn-primary';button.textContent=state.weeklyBrief?'返回工作简报':'完成';button.addEventListener('click',()=>{state.eventFeedback=null;save();$('#event-modal').hidden=true;if(state.weeklyBrief)showWorkBrief()});$('#event-choices').append(button);$('#event-modal').hidden=false}
