  function showEvent(ev){if(ev.id==='openclass')ev={...ev,choices:[...ev.choices,{text:'暂缓安排',hint:'暂无额外影响',effect:{}}]};$('#event-tag').textContent=window.CampusEvents.eventType(ev)+' · '+ev.tag;$('#event-title').textContent=ev.title;$('#event-date').textContent=fmtDate(state.date);$('#event-icon').textContent=ev.kind==='aiInvite'?'函':ev.tag.slice(0,1);$('#event-text').textContent=ev.text;$('#event-choices').innerHTML=ev.choices.map((c,i)=>{const e=c.effect||{},reason=(e.money||0)<0&&state.money< -e.money?'资金不足':(e.ap||0)<0&&state.actionPoints< -e.ap?'行动点不足':'';return `<button class="event-choice" data-choice="${i}" ${reason?'disabled':''}><span>${String(i+1).padStart(2,'0')}</span><div><b>${c.text}</b><small>${(e.money||0)<0?'需资金 '+fmtMoney(-e.money):''}${reason?' · '+reason:''}</small></div><em>›</em></button>`}).join('');if(state.weeklyBrief){$('#event-choices').insertAdjacentHTML('beforeend','<button class="event-choice" id="brief-back">返回工作简报</button>');$('#brief-back').addEventListener('click',showWorkBrief)}$('#event-modal').hidden=false;$$('[data-choice]').forEach(b=>b.addEventListener('click',()=>resolveEvent(ev,Number(b.dataset.choice))))}
  function resolveEvent(ev,index){
    if(ev.kind==='aiInvite'){if(state.eventFeedback)return;const target=school(ev.targetId),beforeAuthority=state.authority,beforeRelation=target.relation;let message;if(index===0){const date=new Date(getDate());date.setDate(date.getDate()+7);if(isGaokaoSeason(date))date.setDate(11);const teachers=state.staffIds.map(staffById).filter(Boolean).sort((a,b)=>teacherCommand(b)-teacherCommand(a));if(!teachers.length)return toast('当前没有可负责联考的教师，请选择其他方案。');const exam={id:`ai-exam-${state.day}-${target.id}`,type:'jointExam',date:isoDay(date),targetId:target.id,classKeys:[1,2,3,4,5,6].map(c=>classKey(2,c)),teacherId:teachers[0].id,status:'scheduled',source:'aiInvite'};state.scheduledEvents.push(exam);target.relation=D.clamp(target.relation+4,0,100);message=`教务处已回复${target.name}，联考安排在 ${fmtDate(date)}，由${teachers[0].name}负责。`;addNews(`接受${target.name}邀请，联考日期定为 ${fmtDate(date)}。`)}else{const authorityLoss=index===1?1:2,relationLoss=index===1?2:5;state.authority-=authorityLoss;target.relation=D.clamp(target.relation-relationLoss,0,100);message=`办公室已向${target.name}${index===1?'说明暂不参加并提出协商':'回复本次不参加'}，教务处将不安排本次联考。`;addNews(`${index===1?'协商延期':'拒绝'}${target.name}联考邀请，校长权威下降 ${authorityLoss}。`)}state.pendingCampusEvent=null;addCalendarEvent('event',ev.title);clampStats();state.eventFeedback={title:ev.title,story:message,changes:`校长权威 ${state.authority-beforeAuthority>=0?'+':''}${state.authority-beforeAuthority}，${target.short}关系 ${target.relation-beforeRelation>=0?'+':''}${target.relation-beforeRelation}`,followup:false};save();renderAll();showEventFeedback();return}
    const choice=ev.choices[index];if(!choice)return;const beforeEvent={money:state.money,teaching:state.teaching,academics:state.academics,studentSatisfaction:state.studentSatisfaction,teacherSatisfaction:state.teacherSatisfaction,staffSatisfaction:state.staffSatisfaction,safety:state.safety,authority:state.authority,prestige:state.prestige,actionPoints:state.actionPoints,adminModifier:state.adminModifier};const beforeRelations=state.schools.map(s=>s.relation);const e=choice.effect||{};if((e.money||0)<0&&state.money< -e.money)return toast('资金不足，请选择其他方案。');if((e.ap||0)<0&&state.actionPoints< -e.ap)return toast('行动点不足，请选择其他方案。');if(state.eventFeedback)return;if(state.weeklyBrief&&!state.weeklyBrief.items.some(x=>x.id===ev.id&&!x.done))return;window.CampusEvents.record(state,ev,index);Object.entries(e).forEach(([k,v])=>{if(k==='money'){state.money+=v;ledger(ev.title,v)}else if(k==='chanceTeaching'){if(Math.random()<.5)state.teaching+=v}else if(k==='relation'){state.schools.forEach(s=>s.relation=D.clamp(s.relation+v,0,100))}else if(k==='ap')state.actionPoints+=v;else if(k==='teacherGrowth')state.teaching+=v*.4;else if(k==='morale')state.studentSatisfaction+=v;else if(k==='management')state.adminModifier+=v;else state[k]=(state[k]||0)+v});state.pendingCampusEvent=null;const briefItem=state.weeklyBrief?.items.find(x=>x.id===ev.id&&!x.done);if(briefItem)briefItem.done=true;addCalendarEvent('event',ev.title);addNews(`${ev.title}：你选择了“${choice.text}”。`);clampStats();const labels={money:'资金',teaching:'教学',academics:'学业',studentSatisfaction:'学生满意',teacherSatisfaction:'教师满意',staffSatisfaction:'职工满意',safety:'安全',authority:'权威',prestige:'声望',actionPoints:'行动点',adminModifier:'管理修正'};const changes=Object.keys(beforeEvent).filter(k=>Math.abs(state[k]-beforeEvent[k])>.001).map(k=>labels[k]+' '+(state[k]-beforeEvent[k]>0?'+':'')+Number((state[k]-beforeEvent[k]).toFixed(2)));if(e.relation)changes.push('校际关系：'+state.schools.map((s,i)=>`${s.short} ${s.relation-beforeRelations[i]>=0?'+':''}${s.relation-beforeRelations[i]}`).join('、'));const branch=window.CampusEventLibrary.followups[ev.id+':'+index]||(index===0&&window.CampusEventLibrary.followups[ev.id]);state.eventFeedback={title:ev.title,story:choice.feedback||`校长决定“${choice.text}”后，相关人员接到了安排。负责人将本次批示记入工作记录，并把处理情况交回办公室。`,changes:changes.join('，')||'本次没有直接数值变化。',followup:!!branch};save();renderAll();showEventFeedback()
  }
  function finishGame(){state.gameOver=true;const rank=[...state.schools].sort((a,b)=>b.power-a.power).findIndex(s=>s.id==='qiu')+1;const grade=state.power>=82?'S':state.power>=70?'A':state.power>=60?'B':'C';save();setTimeout(()=>alert(`任期结束\n\n最终评价：${grade}\n全市排名：第 ${rank} 名\n综合实力：${Math.round(state.power)}\n学校声望：${Math.round(state.prestige)}\n\n你的决定已经成为秋秋一中校史的一部分。`),50)}

