  if(new URLSearchParams(location.search).get('preview')==='battleanger')setTimeout(()=>{const keys=['1-1','1-2','1-5'];examStudents(keys).forEach(s=>s.anger=100);const ev={id:'anger-preview',type:'jointExam',date:isoDay(state.date),targetId:'jin',classKeys:keys,teacherId:state.staffIds[0],status:'scheduled'},result=resolveJointExam(ev,true);result.influence={changed:false,progress:36.42,index:77};showBattle(ev,result)},0);
  if(new URLSearchParams(location.search).get('preview')==='event')setTimeout(()=>showEvent(D.events[5]),0);
